WITH scored AS (SELECT id, dept_id, manager_id, is_remote, MIN(salary) OVER w_part AS last3_min_salary, MAX(salary) OVER w_part AS last3_max_salary, SUM(salary) OVER w_part AS last3_sum_salary, COUNT(salary) OVER w_ordered AS job_title_count_salary FROM employees WINDOW w_part AS (PARTITION BY job_title, manager_id ORDER BY salary, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_ordered AS (PARTITION BY job_title)) SELECT id, dept_id, is_remote, last3_min_salary, last3_max_salary, last3_sum_salary, job_title_count_salary FROM scored ORDER BY id DESC, last3_min_salary LIMIT 10
